SELECT a.chembl_id AS assay_chembl_id, t.target_type, t.tax_id, cs.canonical_smiles, m.chembl_id AS molecule_chembl_id, act.standard_type, act.pchembl_value FROM activities act JOIN assays a ON act.assay_id = a.assay_id JOIN target_dictionary t ON a.tid = t.tid JOIN molecule_dictionary m ON act.molregno = m.molregno JOIN compound_structures cs ON m.molregno = cs.molregno WHERE t.chembl_id = 'CHEMBL1287627' AND act.standard_type = 'IC50' AND act.standard_relation = '=' AND act.pchembl_value IS NOT NULL ORDER BY m.chembl_id, a.chembl_id LIMIT 1000
